      <footer className="rounded-lg border border-border bg-muted/40 px-4 py-3">
        <p className="text-[0.7rem] leading-relaxed text-muted-foreground">
          <span className="font-semibold text-foreground">가상 데이터 · 데모</span> — 실행 이력·
          대상·수치는 전부 가상으로 합성한 데모 데이터이며 실제 시스템·기업 데이터와 무관합니다.
          수동 트리거는 로컬 상태로만 동작하는 시뮬레이션입니다.
        </p>
      </footer>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import {
  ClockCounterClockwiseIcon,
  PlayIcon,
  StopIcon,
} from "@phosphor-icons/react/dist/ssr";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Textarea } from "@/components/ui/textarea";
import { LiveIndicator, type LiveIndicatorStatus } from "@/components/live-indicator";

import { INITIAL_RUNS, type CrawlRun } from "../_data/runs";
import { StepFlow, type StepFlowModel, type StepStatus } from "./step-flow";
import { RunHistoryTable } from "./run-history-table";

const STEP_LABELS = ["수집", "갱신", "감지"] as const;
const TICK_MS = 450;
const PROGRESS_STEP = 11;

type Phase = "idle" | "running";

/** 진행률(0~100)에서 3단계 스텝 상태를 파생한다. */
function deriveStepFlow(phase: Phase, progress: number): StepFlowModel {
  if (phase === "idle") {
    return {
      steps: STEP_LABELS.map((label) => ({ label, status: "idle" as StepStatus })),
      progress: 0,
      progressLabel: "대기 중 · 다음 예약 실행 04:00",
    };
  }
  const activeIndex = progress >= 67 ? 2 : progress >= 34 ? 1 : 0;
  const steps = STEP_LABELS.map((label, i) => {
    let status: StepStatus;
    if (progress >= 100 || i < activeIndex) status = "done";
    else if (i === activeIndex) status = "running";
    else status = "idle";
    return { label, status };
  });
  return {
    steps,
    progress,
    progressLabel: `${STEP_LABELS[activeIndex]} 단계 진행 중…`,
  };
}

/** 입력창의 대상 코드를 파싱해 개수를 센다(줄바꿈·콤마·공백 구분). */
function parseTargetCount(text: string): number {
  return new Set(
    text
      .split(/[\r\n,]+|\s+/)
      .map((t) => t.trim())
      .filter(Boolean),
  ).size;
}

/** 현재 시각을 표시용 고정 포맷 "YYYY-MM-DD HH:MM:SS"(KST 가정)로 만든다. */
function nowStamp(): string {
  const p = (n: number) => (n < 10 ? `0${n}` : `${n}`);
  const d = new Date();
  return (
    `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ` +
    `${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`
  );
}

const LIVE_STATUS: Record<Phase, LiveIndicatorStatus> = {
  idle: "paused",
  running: "live",
};

const LIVE_LABEL: Record<Phase, string> = {
  idle: "스케줄러 대기 · 다음 04:00",
  running: "수동 실행 진행 중",
};

/**
 * 데이터 파이프라인 운영 콘솔의 상호작용 영역 전체를 소유하는 클라이언트
 * 컴포넌트. 수동 트리거 → 실행 중 상태 전이(스텝플로우·라이브 인디케이터·이력
 * 반영)를 로컬 상태만으로 시뮬레이션한다. 실제 네트워크 호출·백엔드는 없다.
 */
export function CrawlerConsole() {
  const [phase, setPhase] = useState<Phase>("idle");
  const [progress, setProgress] = useState(0);
  const [targetInput, setTargetInput] = useState("");
  const [runs, setRuns] = useState<CrawlRun[]>(INITIAL_RUNS);
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const clearTimer = () => {
    if (timerRef.current !== null) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
  };

  useEffect(() => clearTimer, []);

  const prependRun = (status: CrawlRun["status"], updated: number, failed: number) => {
    const count = parseTargetCount(targetInput);
    const target = count > 0 ? `지정 · ${count}` : "전체 소스 · 48";
    setRuns((prev) => [
      {
        id: `run-${Date.now()}`,
        time: nowStamp(),
        target,
        trigger: "수동",
        updated,
        failed,
        status,
      },
      ...prev,
    ]);
  };

  const start = () => {
    if (phase === "running") return;
    setPhase("running");
    setProgress(0);
    timerRef.current = setInterval(() => {
      setProgress((prev) => {
        const next = prev + PROGRESS_STEP;
        if (next >= 100) {
          clearTimer();
          setPhase("idle");
          prependRun("success", 96 + Math.round(Math.random() * 40), 0);
          return 0;
        }
        return next;
      });
    }, TICK_MS);
  };

  const stop = () => {
    if (phase !== "running") return;
    clearTimer();
    setPhase("idle");
    setProgress(0);
    prependRun("stopped", 0, 0);
  };

  const flow = deriveStepFlow(phase, progress);
  const running = phase === "running";

  return (
    <div className="flex flex-col gap-4">
      {/* 스텝플로우 + 스케줄러 상태 */}
      <Card>
        <CardHeader>
          <div className="flex flex-wrap items-center justify-between gap-2">
            <CardTitle className="text-base">수집 파이프라인</CardTitle>
            <LiveIndicator status={LIVE_STATUS[phase]} label={LIVE_LABEL[phase]} />
          </div>
        </CardHeader>
        <CardContent>
          <StepFlow {...flow} />
        </CardContent>
      </Card>

      {/* 수동 트리거 */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <PlayIcon className="size-4" />
            수동 트리거
          </CardTitle>
        </CardHeader>
        <CardContent className="flex flex-col gap-3">
          <div className="flex flex-col gap-1">
            <label htmlFor="crawl-targets" className="text-sm text-muted-foreground">
              대상 소스 코드 (선택 · 줄바꿈·콤마 구분 — 비우면 전체 소스)
            </label>
            <Textarea
              id="crawl-targets"
              rows={3}
              placeholder={"SRC-A01\nSRC-A02, SRC-B14"}
              value={targetInput}
              onChange={(e) => setTargetInput(e.target.value)}
              disabled={running}
            />
          </div>
          <div className="flex flex-wrap items-center gap-3">
            <Button type="button" onClick={start} disabled={running}>
              <PlayIcon className="size-4" />
              {parseTargetCount(targetInput) > 0 ? "지정 대상 실행" : "전체 소스 실행"}
            </Button>
            <Button
              type="button"
              variant="destructive"
              onClick={stop}
              disabled={!running}
            >
              <StopIcon className="size-4" />
              중단
            </Button>
            {running && (
              <span className="inline-flex items-center gap-1.5 text-sm text-muted-foreground">
                <span className="size-2 animate-pulse rounded-full bg-primary" />
                실행 중… {progress}%
              </span>
            )}
          </div>
        </CardContent>
      </Card>

      {/* 실행 이력 */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-base">
            <ClockCounterClockwiseIcon className="size-4" />
            실행 이력
          </CardTitle>
        </CardHeader>
        <CardContent>
          <RunHistoryTable runs={runs} />
        </CardContent>
      </Card>
    </div>
  );
}

import { cn } from "@/lib/utils";
import { Card, CardContent } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import type { CrawlRun, CrawlStatus } from "../_data/runs";

const STATUS_LABEL: Record<CrawlStatus, string> = {
  success: "성공",
  failed: "실패",
  stopped: "중단됨",
};

const STATUS_BADGE_CLASS: Record<CrawlStatus, string> = {
  success: "bg-success/10 text-success border-success/30",
  failed: "bg-destructive/10 text-destructive border-destructive/30",
  stopped: "bg-warning/10 text-warning border-warning/30",
};

/** 실패 행만 옅게 강조 — 이상 실행을 스캔으로 즉시 찾게 한다. */
const ROW_HIGHLIGHT_CLASS: Partial<Record<CrawlStatus, string>> = {
  failed: "bg-destructive/5",
};

function StatusBadge({ status }: Readonly<{ status: CrawlStatus }>) {
  return (
    <span
      className={cn(
        "inline-flex shrink-0 items-center rounded border px-2 py-0.5 font-mono text-xs font-semibold tracking-wide",
        STATUS_BADGE_CLASS[status],
      )}
    >
      {STATUS_LABEL[status]}
    </span>
  );
}

/**
 * 크롤 실행 이력 — 데스크톱은 정렬 테이블, 모바일은 카드 스택으로 리플로우한다.
 * 표는 자체 overflow-x 컨테이너 안에서만 가로 스크롤되어 페이지 가로 오버플로우를
 * 만들지 않는다.
 */
export function RunHistoryTable({ runs }: Readonly<{ runs: CrawlRun[] }>) {
  return (
    <div>
      {/* 모바일: 카드 스택 */}
      <div className="flex flex-col gap-3 sm:hidden">
        {runs.map((run) => (
          <Card key={run.id} className={cn(ROW_HIGHLIGHT_CLASS[run.status])}>
            <CardContent className="flex flex-col gap-2">
              <div className="flex items-start justify-between gap-2">
                <span className="font-mono text-xs text-muted-foreground">{run.time}</span>
                <StatusBadge status={run.status} />
              </div>
              <dl className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-1 text-sm">
                <dt className="text-muted-foreground">대상</dt>
                <dd>
                  {run.target}
                  <span className="ml-1 text-xs text-muted-foreground">({run.trigger})</span>
                </dd>
                <dt className="text-muted-foreground">갱신 / 실패</dt>
                <dd className="tabular-nums">
                  {run.updated.toLocaleString()} /{" "}
                  <span className={run.failed > 0 ? "font-semibold text-destructive" : undefined}>
                    {run.failed.toLocaleString()}
                  </span>
                </dd>
              </dl>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* 데스크톱: 테이블 */}
      <div className="hidden overflow-x-auto sm:block">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>시각</TableHead>
              <TableHead>대상</TableHead>
              <TableHead>방식</TableHead>
              <TableHead className="text-right">갱신</TableHead>
              <TableHead className="text-right">실패</TableHead>
              <TableHead>상태</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {runs.map((run) => (
              <TableRow key={run.id} className={cn(ROW_HIGHLIGHT_CLASS[run.status])}>
                <TableCell className="font-mono text-xs text-muted-foreground whitespace-nowrap">
                  {run.time}
                </TableCell>
                <TableCell className="text-sm">{run.target}</TableCell>
                <TableCell className="text-sm text-muted-foreground">{run.trigger}</TableCell>
                <TableCell className="text-right text-sm tabular-nums">
                  {run.updated.toLocaleString()}
                </TableCell>
                <TableCell
                  className={cn(
                    "text-right text-sm tabular-nums",
                    run.failed > 0 && "font-semibold text-destructive",
                  )}
                >
                  {run.failed.toLocaleString()}
                </TableCell>
                <TableCell>
                  <StatusBadge status={run.status} />
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>
    </div>
  );
}

import {
  CheckCircleIcon,
  CircleIcon,
  SpinnerGapIcon,
  XCircleIcon,
} from "@phosphor-icons/react/dist/ssr";

import { cn } from "@/lib/utils";
import { Progress } from "@/components/ui/progress";

export type StepStatus = "done" | "running" | "error" | "idle";

export interface StepFlowStep {
  label: string;
  status: StepStatus;
}

export interface StepFlowModel {
  steps: StepFlowStep[];
  progress: number;
  progressLabel: string;
}

function StepIcon({ status }: Readonly<{ status: StepStatus }>) {
  if (status === "done")
    return <CheckCircleIcon size={16} weight="fill" className="text-success" />;
  if (status === "running")
    return <SpinnerGapIcon size={16} className="animate-spin text-primary" />;
  if (status === "error")
    return <XCircleIcon size={16} weight="fill" className="text-destructive" />;
  return <CircleIcon size={16} className="text-muted-foreground" />;
}

/**
 * 스텝 플로우 — 번호 노드 + 상태 아이콘 + 화살표 + 진행률 바.
 * bizinfo admin pipeline 의 step-flow 구조·UX만 참고해 순수 프레젠테이션
 * 컴포넌트로 재구성했다(데이터는 상위에서 props 주입, 색은 시맨틱 토큰만).
 * 화살표는 wrap 되므로 모바일에서 세로로 흐른다.
 */
export function StepFlow({ steps, progress, progressLabel }: Readonly<StepFlowModel>) {
  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-wrap items-center gap-1">
        {steps.map((step, i) => (
          <div key={step.label} className="flex items-center gap-1">
            <div
              className={cn(
                "flex items-center gap-1.5 rounded-full border px-2.5 py-1 transition-colors",
                step.status === "running" && "border-primary/40 bg-primary/5",
                step.status === "done" && "border-success/40 bg-success/5",
                step.status === "error" && "border-destructive/40 bg-destructive/5",
              )}
            >
              <StepIcon status={step.status} />
              <span className="text-xs font-medium">{step.label}</span>
            </div>
            {i < steps.length - 1 && (
              <span aria-hidden className="text-muted-foreground">
                →
              </span>
            )}
          </div>
        ))}
      </div>
      <div className="flex flex-col gap-1.5">
        <div className="flex items-center gap-2">
          <Progress value={progress} className="flex-1" />
          <span className="w-10 shrink-0 text-right font-mono text-xs font-semibold tabular-nums">
            {progress}%
          </span>
        </div>
        <p className="text-xs text-muted-foreground">{progressLabel}</p>
      </div>
    </div>
  );
}

/**
 * 크롤러 콘솔 데모용 실행 이력 — 전부 가상으로 합성한 데이터다.
 * 회사·사업자번호 등 실데이터는 포함하지 않으며, 대상은 익명 데이터 소스
 * 코드/집계로만 표현한다. 시각은 로케일·타임존에 흔들리지 않도록 고정 표시
 * 문자열(KST 가정 "YYYY-MM-DD HH:MM:SS")로 둔다.
 */

export type CrawlStatus = "success" | "failed" | "stopped";

export type CrawlTrigger = "자동" | "수동";

export interface CrawlRun {
  /** React key. */
  id: string;
  /** 시작 시각(표시용 고정 문자열). */
  time: string;
  /** 크롤 대상 요약(익명 소스 집계). */
  target: string;
  /** 실행 방식. */
  trigger: CrawlTrigger;
  /** 갱신된 레코드 수. */
